async function upload() {
  const batchSize = 50
  let total = 0
  for (let i = 0; i < ACCESSORIES.length; i += batchSize) {
    const batch = ACCESSORIES.slice(i, i + batchSize)
    const res = await fetch(SUPABASE_URL + '/rest/v1/accessories', {
      method: 'POST',
      headers: {
        'apikey': SUPABASE_KEY,
        'Authorization': 'Bearer ' + SUPABASE_KEY,
        'Content-Type': 'application/json',
        'Prefer': 'return=minimal',
      },
      body: JSON.stringify(batch),
    })
    if (!res.ok) {
      const err = await res.text()
      console.error('Batch ' + (i/batchSize+1) + ' failed:', err)
    } else {
      total += batch.length
      console.log('Batch ' + (i/batchSize+1) + ' uploaded (' + total + '/' + ACCESSORIES.length + ')')
    }
    await new Promise(r => setTimeout(r, 200))
  }
  console.log('Done: ' + total + ' items uploaded')
}

upload().catch(console.error)
